// The smile-explorer pricing engine (C++ compiled to WebAssembly).
//
// The module and its TypeScript types are generated by Bazel (//wasm:engine)
// and copied here by scripts/sync-engine.mjs.

import createEngine from './engine/engine_lib.js';
import type {
  FxVanillaPricingRequest,
  HullWhiteTreeResult,
  HullWhiteTreeSpec,
  MainModule,
  RateCurveSpec,
  VanillaPricingRequest,
  VanillaPricingResult,
} from './engine/engine_lib.js';

export type {
  FxVanillaPricingRequest,
  HullWhiteTreeResult,
  HullWhiteTreeSpec,
  RateCurveSpec,
  VanillaPricingRequest,
  VanillaPricingResult,
};

export const engine: MainModule = await createEngine();

// Index of node (t, i) in the result's per-node arrays (see
// api/pricing_api.h): t is the time index, and 0 <= i <= t counts states from
// the lowest upwards.
export function nodeIndex(t: number, i: number): number {
  return (t * (t + 1)) / 2 + i;
}

export type VolSpec = Parameters<MainModule['evaluateVol']>[0];

export function flatVol(vol: number): VolSpec {
  return {
    model: engine.VolModel.Flat,
    vol,
    termMaturities: [],
    termVols: [],
    smileRange: 0,
    smileStretch: 0,
  };
}

export type PricingOutcome =
  | {result: VanillaPricingResult; error?: undefined}
  | {result?: undefined; error: string};

function attemptPricing(price: () => VanillaPricingResult): PricingOutcome {
  try {
    return {result: price()};
  } catch (e) {
    return {error: e instanceof Error ? e.message : String(e)};
  }
}

export function tryPrice(request: VanillaPricingRequest): PricingOutcome {
  return attemptPricing(() => engine.priceVanilla(request));
}

export function tryPriceFx(request: FxVanillaPricingRequest): PricingOutcome {
  return attemptPricing(() => engine.priceFxVanilla(request));
}
